content.content:
1	/* Phase 1: hero scroll animation. Phase 2: theme tokens, fonts and the headline. Phase 3: aayat on the pages.
2	   Phase 5: the ending. */
3	
4	*,
5	*::before,
6	*::after {
7	  box-sizing: border-box;
8	}
9	
10	/* Dark theme, from design-system/quran-landing/MASTER.md. The background is the footage's own #1F1A18
11	   rather than MASTER's #1C1917 (three shades apart), so the frame's edges disappear without a blend.
12	   Cinzel for the headline and the bright gold were chosen by the user from on-page options. */
13	:root {
14	  --color-background: #1F1A18;
15	  --color-foreground: #FAFAF9;
16	  --color-muted-foreground: #A8A29E;
17	  --color-accent: #D4AF37;
18	  --font-display: Cinzel, 'Trajan Pro', Georgia, serif;
19	  --font-body: Jost, system-ui, sans-serif;
20	  --font-arabic: 'Amiri Quran', 'Scheherazade New', serif;
21	  color-scheme: dark;
22	}
23	
24	html,
25	body {
26	  margin: 0;
27	  background: var(--color-background);
28	  color: var(--color-foreground);
29	  font-family: var(--font-body);
30	}
31	
32	/* No scroll bar: it broke the dark scene. Scrolling works the same without it. */
33	html {
34	  scrollbar-width: none;
35	}
36	
37	html::-webkit-scrollbar {
38	  display: none;
39	}
40	
41	/* A tall section; the stage inside it stays pinned while it scrolls past. Its height is one screen plus the
42	   timeline in main.js (--timeline, in screens, which main.js also sets): the rest, the opening, then a short
43	   hold on the open book before the page moves on to the ending. Phones scroll less far (--pace), because a
44	   finger moves further per swipe than a mouse wheel per click. */
45	.hero {
46	  --timeline: 3.05;
47	  --pace: 1;
48	  position: relative;
49	  height: calc(100vh + var(--timeline) * var(--pace) * 100vh);
50	}
51	
52	.stage {
53	  position: sticky;
54	  top: 0;
55	  height: 100vh;
56	  height: 100svh; /* the book stays whole behind mobile browser bars */
57	  overflow: hidden;
58	}
59	
60	/* The book and its aayat sit together in .subject, which atmosphere.js moves slightly while nobody is
61	   scrolling, inside .book, which makes room for the ending in the "Under the book" option. The light in the
62	   air is a canvas over them (and a second one behind the ending), and never catches clicks. */
63	.book,
64	.subject,
65	.air {
66	  position: absolute;
67	  inset: 0;
68	}
69	
70	.subject canvas,
71	.air {
72	  display: block;
73	  width: 100%;
74	  height: 100%;
75	}
76	
77	.air {
78	  pointer-events: none;
79	}
80	
81	/* The headline, centred in the space under the closed book. --book-h is the book's height on screen,
82	   set by main.js, which also fades it out as the cover starts to open. */
83	.wordmark {
84	  position: absolute;
85	  z-index: 1; /* over .subject: the frame's feathered bottom edge reaches the headline on some screens */
86	  left: 0;
87	  right: 0;
88	  bottom: calc((50% - var(--book-h, 60svh) / 2) / 2);
89	  transform: translateY(50%);
90	  padding: 0 1.5rem;
91	  text-align: center;
92	}
93	
94	.wordmark h1 {
95	  margin: 0;
96	  padding-left: 0.2em; /* balances the letter-spacing after the last letter, so the text sits truly centred */
97	  font-family: var(--font-display);
98	  font-size: clamp(1.125rem, 0.9rem + 1vw, 1.625rem);
99	  font-weight: 500;
100	  line-height: 1.2;
101	  letter-spacing: 0.2em;
102	  text-transform: uppercase;
103	  color: var(--color-accent);
104	}
105	
106	.wordmark p {
107	  margin: 0.7em 0 0;
108	  font-size: clamp(0.8125rem, 0.75rem + 0.3vw, 0.9375rem);
109	  font-weight: 300;
110	  letter-spacing: 0.06em;
111	  color: var(--color-muted-foreground);
112	}
113	
114	/* Aayat, laid over the open book's pages. The numbers are page positions in the 1280x720 footage:
115	   left page x 262-636, right page x 645-1020, both y 80-640. main.js sets --s (the book's scale) and
116	   --x0/--y0 (where the footage's corner sits once the book is open), and each group's opacity. */
117	.aayat {
118	  position: absolute;
119	  inset: 0;
120	  pointer-events: none;
121	}
122	
123	.group {
124	  position: absolute;
125	  inset: 0;
126	  opacity: 0;
127	  transition: opacity 600ms cubic-bezier(0.32, 0.72, 0, 1); /* main.js only switches opacity between 0 and 1 */
128	  mix-blend-mode: multiply; /* the ink sits in the paper, so the paper's shading shows through it */
129	}
130	
131	.page {
132	  position: absolute;
133	  top: calc(var(--y0, 0px) + 80px * var(--s, 1));
134	  width: calc(375px * var(--s, 1));
135	  height: calc(560px * var(--s, 1));
136	  padding: calc(56px * var(--s, 1)) calc(40px * var(--s, 1));
137	  display: flex;
138	  flex-direction: column;
139	  justify-content: safe center;
140	  gap: 1.25em;
141	  overflow: hidden;
142	  text-align: center;
143	  color: #2B211B; /* dark ink, 14:1 on the cream page */
144	}
145	
146	.page p {
147	  margin: 0;
148	}
149	
150	.page.right {
151	  left: calc(var(--x0, 0px) + 645px * var(--s, 1));
152	  font-size: calc(30px * var(--s, 1));
153	}
154	
155	.page.left {
156	  left: calc(var(--x0, 0px) + 262px * var(--s, 1));
157	  font-size: calc(16px * var(--s, 1));
158	}
159	
160	.arabic {
161	  font-family: var(--font-arabic);
162	  line-height: 2.2; /* room for the marks above and below the letters */
163	}
164	
165	.marker {
166	  color: #A16207; /* gold only for the small accents */
167	}
168	
169	.surah {
170	  padding-left: 0.15em;
171	  font-family: var(--font-display);
172	  font-size: 1.2em;
173	  letter-spacing: 0.15em;
174	  text-transform: uppercase;
175	  color: #8A6A1F;
176	}
177	
178	.meaning {
179	  display: none;
180	  font-weight: 400;
181	  line-height: 1.6;
182	  color: #3A302A;
183	}
184	
185	.ref {
186	  font-size: 0.85em;
187	  letter-spacing: 0.08em;
188	  color: #6B5E55;
189	}
190	
191	/* Phase 5: the ending, one line and two ways in, on the screen after the book. The gold dust carries on behind it
192	   on a second canvas (atmosphere.js). The spacing, 4px corners, no shadow and gentle rise follow
193	   taste-skill:minimalist-skill; one gold button leads and the other stays quieter (ui-ux-pro-max: primary-action). */
194	.close {
195	  position: relative;
196	  isolation: isolate; /* keeps .inner over the dust without lifting it over the options panels */
197	  display: grid;
198	  place-items: center;
199	  min-height: 100vh;
200	  min-height: 100svh;
201	  padding: 6rem 1.5rem;
202	}
203	
204	.close .inner {
205	  position: relative;
206	  z-index: 1;
207	  display: flex;
208	  flex-direction: column;
209	  align-items: center;
210	  gap: 2.25rem;
211	  width: 100%;
212	  max-width: 40rem;
213	  text-align: center;
214	}
215	
216	/* The ending arrives in order: the star and its rules, the line, then the buttons, 120ms apart (ui-ux-pro-max
217	   motion data, "Scroll Reveal": children a beat apart, a small rise). main.js sets .pending until it scrolls into
218	   view. Leaving is quicker than arriving. */
219	.close .inner > * {
220	  transition:
221	    opacity 700ms cubic-bezier(0.16, 1, 0.3, 1),
222	    transform 700ms cubic-bezier(0.16, 1, 0.3, 1);
223	  transition-delay: calc(var(--delay, 0ms) + var(--i, 0) * 120ms);
224	}
225	
226	.close .inner > :nth-child(2) {
227	  --i: 1;
228	}
229	
230	.close .inner > :nth-child(3) {
231	  --i: 2;
232	}
233	
234	.close.pending .inner > * {
235	  opacity: 0;
236	  transform: translateY(16px);
237	  transition-duration: 250ms;
238	  transition-delay: 0s;
239	}
240	
241	/* Behind the words, and never over the book: a warm light where the book's light was, and a large gold star in thin
242	   lines that turns once every four minutes. From taste-skill:minimalist-skill: a section shouldn't be empty and flat
243	   (soft light, fine geometric lines), and may have one very slow ambient movement. */
244	.close .backdrop {
245	  position: absolute;
246	  inset: 0;
247	  width: 100%;
248	  height: 100%;
249	  overflow: hidden;
250	  pointer-events: none;
251	}
252	
253	.close .backdrop::before {
254	  content: '';
255	  position: absolute;
256	  inset: 0;
257	  background: radial-gradient(ellipse 50% 45% at 50% 50%, rgba(212, 175, 55, 0.1), rgba(212, 175, 55, 0.04) 50%, rgba(212, 175, 55, 0));
258	}
259	
260	.rosette {
261	  position: absolute;
262	  top: 50%;
263	  left: 50%;
264	  width: min(96vmin, 52rem);
265	  height: auto;
266	  translate: -50% -50%;
267	  overflow: visible;
268	  fill: none;
269	  stroke-width: 1;
270	  opacity: 0.16;
271	  animation: turn 240s linear infinite;
272	}
273	
274	@keyframes turn {
275	  to {
276	    rotate: 1turn;
277	  }
278	}
279	
280	/* A small gold star between two fine rules, like the gold tooling on the cover. The rules draw outward and the star
281	   turns into place as the ending arrives. */
282	.ornament {
283	  width: 13rem;
284	  height: auto;
285	  margin-bottom: -0.75rem;
286	  overflow: visible;
287	  fill: none;
288	  stroke: var(--color-accent);
289	  stroke-width: 1;
290	}
291	
292	.rosette *,
293	.ornament * {
294	  vector-effect: non-scaling-stroke; /* hairlines at any size */
295	}
296	
297	.ornament circle {
298	  fill: var(--color-accent);
299	  stroke: none;
300	}
301	
302	.ornament .rule {
303	  opacity: 0.6;
304	  transform-box: fill-box;
305	  transition: transform 1000ms cubic-bezier(0.16, 1, 0.3, 1) calc(var(--delay, 0ms) + 200ms);
306	}
307	
308	.ornament .left {
309	  transform-origin: right center;
310	}
311	
312	.ornament .right {
313	  transform-origin: left center;
314	}
315	
316	.ornament .star {
317	  transform-box: fill-box;
318	  transform-origin: center;
319	  transition:
320	    opacity 600ms ease var(--delay, 0ms),
321	    transform 1000ms cubic-bezier(0.16, 1, 0.3, 1) var(--delay, 0ms);
322	}
323	
324	.close.pending .ornament .rule {
325	  transform: scaleX(0);
326	  transition-duration: 250ms;
327	  transition-delay: 0s;
328	}
329	
330	.close.pending .ornament .star {
331	  opacity: 0;
332	  transform: rotate(-90deg) scale(0.5);
333	  transition-duration: 250ms;
334	  transition-delay: 0s;
335	}
336	
337	/* A quiet name at the very bottom. The headline stands in until the site name is chosen. */
338	.signoff {
339	  position: absolute;
340	  z-index: 1;
341	  right: 0;
342	  bottom: 2rem;
343	  left: 0;
344	  margin: 0;
345	  padding-left: 0.3em; /* balances the letter-spacing after the last letter */
346	  font-family: var(--font-display);
347	  font-size: 0.75rem;
348	  letter-spacing: 0.3em;
349	  text-align: center;
350	  text-transform: uppercase;
351	  color: var(--color-accent);
352	  opacity: 0.8; /* still over 5:1 on the background */
353	  transition: opacity 700ms ease 600ms;
354	}
355	
356	.close.pending .signoff {
357	  opacity: 0;
358	  transition-delay: 0s;
359	}
360	
361	.close h2 {
362	  margin: 0;
363	  max-width: 30ch;
364	  font-size: clamp(1.375rem, 1.1rem + 1.1vw, 2rem);
365	  font-weight: 300;
366	  line-height: 1.35;
367	  letter-spacing: 0.01em;
368	  text-wrap: balance;
369	}
370	
371	.entry {
372	  display: flex;
373	  flex-wrap: wrap;
374	  justify-content: center;
375	  gap: 0.75rem 1rem;
376	}
377	
378	.button {
379	  display: inline-flex;
380	  align-items: center;
381	  justify-content: center;
382	  min-height: 48px;
383	  padding: 0 1.75rem;
384	  border: 1px solid var(--color-accent);
385	  border-radius: 4px;
386	  font-size: 0.9375rem;
387	  letter-spacing: 0.06em;
388	  color: var(--color-accent); /* 8:1 on the background */
389	  text-decoration: none;
390	  cursor: pointer;
391	  transition:
392	    background-color 200ms ease,
393	    border-color 200ms ease,
394	    color 200ms ease,
395	    transform 200ms ease;
396	}
397	
398	.button.primary {
399	  background: var(--color-accent);
400	  color: var(--color-background); /* 8:1 on the gold */
401	}
402	
403	.button:hover {
404	  background: rgba(212, 175, 55, 0.1);
405	}
406	
407	.button.primary:hover {
408	  border-color: #E2C35C;
409	  background: #E2C35C;
410	}
411	
412	.button:active {
413	  transform: scale(0.98);
414	}
415	
416	.button:focus-visible {
417	  outline: 2px solid var(--color-accent);
418	  outline-offset: 4px;
419	}
420	
421	@media (max-width: 767px) {
422	  .close {
423	    padding: 4rem 1.5rem;
424	  }
425	
426	  .signoff {
427	    bottom: 1.5rem;
428	  }
429	
430	  .entry {
431	    flex-direction: column;
432	    width: 100%;
433	    max-width: 20rem;
434	  }
435	}
436	
437	@media (max-width: 767px) {
438	  .hero {
439	    --pace: 0.666; /* two thirds as far */
440	  }
441	
442	  /* The pages are too small for a second block of text, so the left page's text sits under the book. */
443	  .group {
444	    mix-blend-mode: normal;
445	  }
446	
447	  .page.left {
448	    left: 1.5rem;
449	    right: 1.5rem;
450	    width: auto;
451	    top: calc(var(--y0, 0px) + 650px * var(--s, 1) + 1rem);
452	    height: calc(var(--y0, 0px) + 70px * var(--s, 1) - 2rem);
453	    padding: 0;
454	    font-size: 0.875rem;
455	    color: var(--color-muted-foreground);
456	  }
457	
458	  .page.left .surah {
459	    color: var(--color-accent);
460	  }
461	
462	  .page.left .meaning,
463	  .page.left .ref {
464	    color: var(--color-muted-foreground);
465	  }
466	}
467	
468	/* Reduced motion: no scrubbing, just the open book with a random group of aayat. */
469	.still .hero {
470	  height: auto;
471	}
472	
473	.still .group {
474	  transition: none;
475	}
476	
477	.still .close.pending .inner > *,
478	.still .close.pending .signoff,
479	.still .close.pending .ornament .star {
480	  opacity: 1;
481	  transform: none;
482	}
483	
484	.still .close.pending .ornament .rule {
485	  transform: none;
486	}
487	
488	.still .rosette {
489	  animation: none;
490	}
491	
492	/* TRYOUT: phase 3 options, set on <html> by main.js. Once the user picks, move the picks above and
493	   delete everything below. */
494	[data-arabic='scheherazade'] {
495	  --font-arabic: 'Scheherazade New', 'Amiri Quran', serif;
496	}
497	
498	[data-left='meaning'] .meaning {
499	  display: block;
500	}
501	
502	/* Phase 4, "Aayat while moving: Fix B" (set by atmosphere.js): plain ink, as on phones. */
503	[data-ink='flat'] .group {
504	  mix-blend-mode: normal;
505	}
506	
507	.tryout input[type='range'] {
508	  width: 10em;
509	  accent-color: #d4af37;
510	}
511	
512	.tryout output {
513	  min-width: 7em;
514	  font-variant-numeric: tabular-nums;
515	}
516	
517	/* Free-text fields (window.addText in main.js), for typing a headline, sentence or label exactly as wanted. */
518	.tryout input[type='text'] {
519	  flex: 1;
520	  min-width: 12em;
521	  padding: 6px 8px;
522	  border: 1px solid #5c5048;
523	  border-radius: 6px;
524	  background: rgba(255, 255, 255, 0.06);
525	  font: inherit;
526	  color: #e7e0d8;
527	}
528	
529	.tryout input[type='text']:focus-visible {
530	  outline: 2px solid #d4af37;
531	  outline-offset: 1px;
532	}
533	
534	.tryout {
535	  position: fixed;
536	  right: 12px; /* bottom-right, clear of the headline picker (wordmark-options.js) in the bottom-left */
537	  bottom: 12px;
538	  max-width: calc(100vw - 24px);
539	  max-height: calc(100svh - 24px); /* scrolls inside itself on a phone */
540	  overflow-y: auto;
541	  padding: 10px 12px;
542	  border: 1px solid #3F3A37;
543	  border-radius: 12px;
544	  background: rgba(0, 0, 0, 0.7);
545	  font: 13px/1 system-ui, sans-serif;
546	  color: #e7e0d8;
547	}
548	
549	.tryout .readout {
550	  max-width: 34em;
551	  margin: 10px 0 2px;
552	  line-height: 1.4;
553	  color: #A8A29E;
554	  font-variant-numeric: tabular-nums;
555	}
556	
557	.tryout summary {
558	  padding: 4px 0;
559	  cursor: pointer;
560	}
561	
562	/* Groups of options inside the panel, from tryoutGroup in main.js. */
563	.tryout details {
564	  margin-top: 10px;
565	  padding-top: 4px;
566	  border-top: 1px solid #3F3A37;
567	}
568	
569	.tryout div {
570	  display: flex;
571	  flex-wrap: wrap;
572	  align-items: center;
573	  gap: 6px;
574	  margin-top: 8px;
575	}
576	
577	.tryout span {
578	  min-width: 10em;
579	  color: #A8A29E;
580	}
581	
582	.tryout button {
583	  padding: 10px 14px;
584	  border: 1px solid #5c5048;
585	  border-radius: 999px;
586	  background: transparent;
587	  color: #e7e0d8;
588	  font: inherit;
589	  cursor: pointer;
590	}
591	
592	.tryout button[aria-pressed='true'] {
593	  border-color: #d4af37;
594	  color: #d4af37;
595	}
596	
597	/* TRYOUT, phones only: how far to scroll through the hero, and where the surah name goes. */
598	@media (max-width: 767px) {
599	  [data-phone-scroll='medium'] .hero {
600	    --pace: 0.512;
601	  }
602	
603	  [data-phone-scroll='short'] .hero {
604	    --pace: 0.366;
605	  }
606	
607	  [data-phone-left='page'] .page.left {
608	    left: calc(var(--x0, 0px) + 262px * var(--s, 1));
609	    right: auto;
610	    top: calc(var(--y0, 0px) + 80px * var(--s, 1));
611	    width: calc(375px * var(--s, 1));
612	    height: calc(560px * var(--s, 1));
613	    padding: calc(56px * var(--s, 1)) calc(16px * var(--s, 1));
614	    font-size: max(9px, calc(16px * var(--s, 1)));
615	    color: #2B211B;
616	  }
617	
618	  [data-phone-left='page'] .page.left .surah {
619	    color: #8A6A1F;
620	  }
621	
622	  [data-phone-left='page'] .page.left .ref {
623	    color: #6B5E55;
624	  }
625	
626	  [data-phone-left='page'] .page.left .meaning {
627	    display: none; /* too long for a page this small */
628	  }
629	}
630	
631	/* TRYOUT, phase 5: set on <html> by ending-options.js. Once the user picks, move the chosen rules up to the ending's
632	   styles and delete the rest, with .book's transition and endAt/placeEnding in main.js if "After the book" wins. */
633	
634	/* "Under the book", computers only. The ending shares the book's last screen: .close is pulled up over it, and when
635	   scrolling reaches the end (main.js sets .ended) the open book rises and shrinks by what main.js works out for the
636	   screen, and the ending fades in underneath. Going back is quicker than arriving. */
637	.book {
638	  transition: transform 700ms cubic-bezier(0.32, 0.72, 0, 1);
639	}
640	
641	@media (min-width: 768px) {
642	  [data-ending='under']:not(.still) .hero.ended .book {
643	    transform: translateY(var(--end-y, 0px)) scale(var(--end-scale, 1));
644	    transition-duration: 1100ms;
645	  }
646	
647	  [data-ending='under']:not(.still) .close {
648	    display: block;
649	    height: 100vh;
650	    height: 100svh;
651	    min-height: 0;
652	    margin-top: -100vh;
653	    margin-top: -100svh;
654	    padding: 0;
655	    pointer-events: none;
656	  }
657	
658	  [data-ending='under']:not(.still) .close .air,
659	  [data-ending='under']:not(.still) .close .backdrop,
660	  [data-ending='under']:not(.still) .close .signoff {
661	    display: none; /* the open book and its own dust are the picture here */
662	  }
663	
664	  [data-ending='under']:not(.still) .close .inner {
665	    --delay: 450ms; /* the words follow the book's move */
666	    position: absolute;
667	    top: var(--end-top, 75%);
668	    left: 0;
669	    right: 0;
670	    margin: 0 auto;
671	    padding: 0 1.5rem;
672	    visibility: hidden;
673	    transition: visibility 0s 300ms;
674	  }
675	
676	  [data-ending='under']:not(.still) .hero.ended + .close .inner {
677	    visibility: visible;
678	    pointer-events: auto;
679	    transition: none;
680	  }
681	}
682	
683	/* Button looks. "Gold and outline" is the default, above. */
684	[data-buttons='outline'] .button.primary {
685	  background: transparent;
686	  color: var(--color-accent);
687	}
688	
689	[data-buttons='outline'] .button.primary:hover {
690	  border-color: var(--color-accent);
691	  background: rgba(212, 175, 55, 0.12);
692	}
693	
694	[data-buttons='outline'] .button:not(.primary) {
695	  border-color: rgba(250, 250, 249, 0.3);
696	  color: var(--color-foreground);
697	}
698	
699	[data-buttons='outline'] .button:not(.primary):hover {
700	  border-color: rgba(250, 250, 249, 0.6);
701	  background: rgba(250, 250, 249, 0.06);
702	}
703	
704	[data-buttons='text'] .entry {
705	  gap: 0.5rem 2.5rem;
706	}
707	
708	[data-buttons='text'] .button,
709	[data-buttons='text'] .button:hover,
710	[data-buttons='text'] .button.primary,
711	[data-buttons='text'] .button.primary:hover {
712	  position: relative;
713	  padding: 0 0.25rem;
714	  border-color: transparent;
715	  background: transparent;
716	  color: var(--color-foreground);
717	}
718	
719	[data-buttons='text'] .button.primary,
720	[data-buttons='text'] .button.primary:hover {
721	  color: var(--color-accent);
722	}
723	
724	[data-buttons='text'] .button::after {
725	  content: '';
726	  position: absolute;
727	  left: 0.25rem;
728	  right: 0.25rem;
729	  bottom: 11px;
730	  height: 1px;
731	  background: currentColor;
732	  opacity: 0.45;
733	  transform: scaleX(0.4);
734	  transition:
735	    opacity 200ms ease,
736	    transform 300ms cubic-bezier(0.16, 1, 0.3, 1);
737	}
738	
739	[data-buttons='text'] .button:hover::after,
740	[data-buttons='text'] .button:focus-visible::after {
741	  opacity: 1;
742	  transform: none;
743	}
744	
745	/* What sits behind the words, and the name at the very end. "Light and star" and "Show" are the defaults, above. */
746	[data-backdrop='plain'] .close .backdrop {
747	  display: none;
748	}
749	
750	[data-backdrop='light'] .rosette {
751	  display: none;
752	}
