file.content:
/* Phase 1: hero scroll animation. Phase 2: theme tokens, fonts and the headline. Phase 3: aayat on the pages.
   Phase 5: the ending. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

/* Dark theme, from design-system/quran-landing/MASTER.md. The background is the footage's own #1F1A18
   rather than MASTER's #1C1917 (three shades apart), so the frame's edges disappear without a blend.
   Cinzel for the headline and the bright gold were chosen by the user from on-page options. */
:root {
  --color-background: #1F1A18;
  --color-foreground: #FAFAF9;
  --color-muted-foreground: #A8A29E;
  --color-accent: #D4AF37;
  --font-display: Cinzel, 'Trajan Pro', Georgia, serif;
  --font-body: Jost, system-ui, sans-serif;
  --font-arabic: 'Amiri Quran', 'Scheherazade New', serif;
  color-scheme: dark;
}

html,
body {
  margin: 0;
  background: var(--color-background);
  color: var(--color-foreground);
  font-family: var(--font-body);
}

/* No scroll bar: it broke the dark scene. Scrolling works the same without it. */
html {
  scrollbar-width: none;
}

html::-webkit-scrollbar {
  display: none;
}

/* A tall section; the stage inside it stays pinned while it scrolls past. Its height is one screen plus the
   timeline in main.js (--timeline, in screens, which main.js also sets): the rest, the opening, then a short
   hold on the open book before the page moves on to the ending. Phones scroll less far (--pace), because a
   finger moves further per swipe than a mouse wheel per click. */
.hero {
  --timeline: 3.05;
  --pace: 1;
  position: relative;
  height: calc(100vh + var(--timeline) * var(--pace) * 100vh);
}

.stage {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh; /* the book stays whole behind mobile browser bars */
  overflow: hidden;
}

/* The book and its aayat sit together in .subject, which atmosphere.js moves slightly while nobody is
   scrolling, inside .book, which makes room for the ending in the "Under the book" option. The light in the
   air is a canvas over them (and a second one behind the ending), and never catches clicks. */
.book,
.subject,
.air {
  position: absolute;
  inset: 0;
}

.subject canvas,
.air {
  display: block;
  width: 100%;
  height: 100%;
}

.air {
  pointer-events: none;
}

/* The headline, centred in the space under the closed book. --book-h is the book's height on screen,
   set by main.js, which also fades it out as the cover starts to open. */
.wordmark {
  position: absolute;
  z-index: 1; /* over .subject: the frame's feathered bottom edge reaches the headline on some screens */
  left: 0;
  right: 0;
  bottom: calc((50% - var(--book-h, 60svh) / 2) / 2);
  transform: translateY(50%);
  padding: 0 1.5rem;
  text-align: center;
}

.wordmark h1 {
  margin: 0;
  padding-left: 0.2em; /* balances the letter-spacing after the last letter, so the text sits truly centred */
  font-family: var(--font-display);
  font-size: clamp(1.125rem, 0.9rem + 1vw, 1.625rem);
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-accent);
}

.wordmark p {
  margin: 0.7em 0 0;
  font-size: clamp(0.8125rem, 0.75rem + 0.3vw, 0.9375rem);
  font-weight: 300;
  letter-spacing: 0.06em;
  color: var(--color-muted-foreground);
}

/* Aayat, laid over the open book's pages. The numbers are page positions in the 1280x720 footage:
   left page x 262-636, right page x 645-1020, both y 80-640. main.js sets --s (the book's scale) and
   --x0/--y0 (where the footage's corner sits once the book is open), and each group's opacity. */
.aayat {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.group {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 600ms cubic-bezier(0.32, 0.72, 0, 1); /* main.js only switches opacity between 0 and 1 */
  mix-blend-mode: multiply; /* the ink sits in the paper, so the paper's shading shows through it */
}

.page {
  position: absolute;
  top: calc(var(--y0, 0px) + 80px * var(--s, 1));
  width: calc(375px * var(--s, 1));
  height: calc(560px * var(--s, 1));
  padding: calc(56px * var(--s, 1)) calc(40px * var(--s, 1));
  display: flex;
  flex-direction: column;
  justify-content: safe center;
  gap: 1.25em;
  overflow: hidden;
  text-align: center;
  color: #2B211B; /* dark ink, 14:1 on the cream page */
}

.page p {
  margin: 0;
}

.page.right {
  left: calc(var(--x0, 0px) + 645px * var(--s, 1));
  font-size: calc(30px * var(--s, 1));
}

.page.left {
  left: calc(var(--x0, 0px) + 262px * var(--s, 1));
  font-size: calc(16px * var(--s, 1));
}

.arabic {
  font-family: var(--font-arabic);
  line-height: 2.2; /* room for the marks above and below the letters */
}

.marker {
  color: #A16207; /* gold only for the small accents */
}

.surah {
  padding-left: 0.15em;
  font-family: var(--font-display);
  font-size: 1.2em;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: #8A6A1F;
}

.meaning {
  display: none;
  font-weight: 400;
  line-height: 1.6;
  color: #3A302A;
}

.ref {
  font-size: 0.85em;
  letter-spacing: 0.08em;
  color: #6B5E55;
}

/* Phase 5: the ending, one line and two ways in, on the screen after the book. The gold dust carries on behind it
   on a second canvas (atmosphere.js). The spacing, 4px corners, no shadow and gentle rise follow
   taste-skill:minimalist-skill; one gold button leads and the other stays quieter (ui-ux-pro-max: primary-action). */
.close {
  position: relative;
  isolation: isolate; /* keeps .inner over the dust without lifting it over the options panels */
  display: grid;
  place-items: center;
  min-height: 100vh;
  min-height: 100svh;
  padding: 6rem 1.5rem;
}

.close .inner {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2.25rem;
  width: 100%;
  max-width: 40rem;
  text-align: center;
}

/* The ending arrives in order: the star and its rules, the line, then the buttons, 120ms apart (ui-ux-pro-max
   motion data, "Scroll Reveal": children a beat apart, a small rise). main.js sets .pending until it scrolls into
   view. Leaving is quicker than arriving. */
.close .inner > * {
  transition:
    opacity 700ms cubic-bezier(0.16, 1, 0.3, 1),
    transform 700ms cubic-bezier(0.16, 1, 0.3, 1);
  transition-delay: calc(var(--delay, 0ms) + var(--i, 0) * 120ms);
}

.close .inner > :nth-child(2) {
  --i: 1;
}

.close .inner > :nth-child(3) {
  --i: 2;
}

.close.pending .inner > * {
  opacity: 0;
  transform: translateY(16px);
  transition-duration: 250ms;
  transition-delay: 0s;
}

/* Behind the words, and never over the book: a warm light where the book's light was, and a large gold star in thin
   lines that turns once every four minutes. From taste-skill:minimalist-skill: a section shouldn't be empty and flat
   (soft light, fine geometric lines), and may have one very slow ambient movement. */
.close .backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  pointer-events: none;
}

.close .backdrop::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 50% 45% at 50% 50%, rgba(212, 175, 55, 0.1), rgba(212, 175, 55, 0.04) 50%, rgba(212, 175, 55, 0));
}

.rosette {
  position: absolute;
  top: 50%;
  left: 50%;
  width: min(96vmin, 52rem);
  height: auto;
  translate: -50% -50%;
  overflow: visible;
  fill: none;
  stroke-width: 1;
  opacity: 0.16;
  animation: turn 240s linear infinite;
}

@keyframes turn {
  to {
    rotate: 1turn;
  }
}

/* A small gold star between two fine rules, like the gold tooling on the cover. The rules draw outward and the star
   turns into place as the ending arrives. */
.ornament {
  width: 13rem;
  height: auto;
  margin-bottom: -0.75rem;
  overflow: visible;
  fill: none;
  stroke: var(--color-accent);
  stroke-width: 1;
}

.rosette *,
.ornament * {
  vector-effect: non-scaling-stroke; /* hairlines at any size */
}

.ornament circle {
  fill: var(--color-accent);
  stroke: none;
}

.ornament .rule {
  opacity: 0.6;
  transform-box: fill-box;
  transition: transform 1000ms cubic-bezier(0.16, 1, 0.3, 1) calc(var(--delay, 0ms) + 200ms);
}

.ornament .left {
  transform-origin: right center;
}

.ornament .right {
  transform-origin: left center;
}

.ornament .star {
  transform-box: fill-box;
  transform-origin: center;
  transition:
    opacity 600ms ease var(--delay, 0ms),
    transform 1000ms cubic-bezier(0.16, 1, 0.3, 1) var(--delay, 0ms);
}

.close.pending .ornament .rule {
  transform: scaleX(0);
  transition-duration: 250ms;
  transition-delay: 0s;
}

.close.pending .ornament .star {
  opacity: 0;
  transform: rotate(-90deg) scale(0.5);
  transition-duration: 250ms;
  transition-delay: 0s;
}

/* A quiet name at the very bottom. The headline stands in until the site name is chosen. */
.signoff {
  position: absolute;
  z-index: 1;
  right: 0;
  bottom: 2rem;
  left: 0;
  margin: 0;
  padding-left: 0.3em; /* balances the letter-spacing after the last letter */
  font-family: var(--font-display);
  font-size: 0.75rem;
  letter-spacing: 0.3em;
  text-align: center;
  text-transform: uppercase;
  color: var(--color-accent);
  opacity: 0.8; /* still over 5:1 on the background */
  transition: opacity 700ms ease 600ms;
}

.close.pending .signoff {
  opacity: 0;
  transition-delay: 0s;
}

.close h2 {
  margin: 0;
  max-width: 30ch;
  font-size: clamp(1.375rem, 1.1rem + 1.1vw, 2rem);
  font-weight: 300;
  line-height: 1.35;
  letter-spacing: 0.01em;
  text-wrap: balance;
}

.entry {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.75rem 1rem;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0 1.75rem;
  border: 1px solid var(--color-accent);
  border-radius: 4px;
  font-size: 0.9375rem;
  letter-spacing: 0.06em;
  color: var(--color-accent); /* 8:1 on the background */
  text-decoration: none;
  cursor: pointer;
  transition:
    background-color 200ms ease,
    border-color 200ms ease,
    color 200ms ease,
    transform 200ms ease;
}

.button.primary {
  background: var(--color-accent);
  color: var(--color-background); /* 8:1 on the gold */
}

.button:hover {
  background: rgba(212, 175, 55, 0.1);
}

.button.primary:hover {
  border-color: #E2C35C;
  background: #E2C35C;
}

.button:active {
  transform: scale(0.98);
}

.button:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 4px;
}

@media (max-width: 767px) {
  .close {
    padding: 4rem 1.5rem;
  }

  .signoff {
    bottom: 1.5rem;
  }

  .entry {
    flex-direction: column;
    width: 100%;
    max-width: 20rem;
  }
}

@media (max-width: 767px) {
  .hero {
    --pace: 0.666; /* two thirds as far */
  }

  /* The pages are too small for a second block of text, so the left page's text sits under the book. */
  .group {
    mix-blend-mode: normal;
  }

  .page.left {
    left: 1.5rem;
    right: 1.5rem;
    width: auto;
    top: calc(var(--y0, 0px) + 650px * var(--s, 1) + 1rem);
    height: calc(var(--y0, 0px) + 70px * var(--s, 1) - 2rem);
    padding: 0;
    font-size: 0.875rem;
    color: var(--color-muted-foreground);
  }

  .page.left .surah {
    color: var(--color-accent);
  }

  .page.left .meaning,
  .page.left .ref {
    color: var(--color-muted-foreground);
  }
}

/* Reduced motion: no scrubbing, just the open book with a random group of aayat. */
.still .hero {
  height: auto;
}

.still .group {
  transition: none;
}

.still .close.pending .inner > *,
.still .close.pending .signoff,
.still .close.pending .ornament .star {
  opacity: 1;
  transform: none;
}

.still .close.pending .ornament .rule {
  transform: none;
}

.still .rosette {
  animation: none;
}

/* TRYOUT: phase 3 options, set on <html> by main.js. Once the user picks, move the picks above and
   delete everything below. */
[data-arabic='scheherazade'] {
  --font-arabic: 'Scheherazade New', 'Amiri Quran', serif;
}

[data-left='meaning'] .meaning {
  display: block;
}

/* Phase 4, "Aayat while moving: Fix B" (set by atmosphere.js): plain ink, as on phones. */
[data-ink='flat'] .group {
  mix-blend-mode: normal;
}

.tryout input[type='range'] {
  width: 10em;
  accent-color: #d4af37;
}

.tryout output {
  min-width: 7em;
  font-variant-numeric: tabular-nums;
}

/* Free-text fields (window.addText in main.js), for typing a headline, sentence or label exactly as wanted. */
.tryout input[type='text'] {
  flex: 1;
  min-width: 12em;
  padding: 6px 8px;
  border: 1px solid #5c5048;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.06);
  font: inherit;
  color: #e7e0d8;
}

.tryout input[type='text']:focus-visible {
  outline: 2px solid #d4af37;
  outline-offset: 1px;
}

.tryout {
  position: fixed;
  right: 12px; /* bottom-right, clear of the headline picker (wordmark-options.js) in the bottom-left */
  bottom: 12px;
  max-width: calc(100vw - 24px);
  max-height: calc(100svh - 24px); /* scrolls inside itself on a phone */
  overflow-y: auto;
  padding: 10px 12px;
  border: 1px solid #3F3A37;
  border-radius: 12px;
  background: rgba(0, 0, 0, 0.7);
  font: 13px/1 system-ui, sans-serif;
  color: #e7e0d8;
}

.tryout .readout {
  max-width: 34em;
  margin: 10px 0 2px;
  line-height: 1.4;
  color: #A8A29E;
  font-variant-numeric: tabular-nums;
}

.tryout summary {
  padding: 4px 0;
  cursor: pointer;
}

/* Groups of options inside the panel, from tryoutGroup in main.js. */
.tryout details {
  margin-top: 10px;
  padding-top: 4px;
  border-top: 1px solid #3F3A37;
}

.tryout div {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-top: 8px;
}

.tryout span {
  min-width: 10em;
  color: #A8A29E;
}

.tryout button {
  padding: 10px 14px;
  border: 1px solid #5c5048;
  border-radius: 999px;
  background: transparent;
  color: #e7e0d8;
  font: inherit;
  cursor: pointer;
}

.tryout button[aria-pressed='true'] {
  border-color: #d4af37;
  color: #d4af37;
}

/* TRYOUT, phones only: how far to scroll through the hero, and where the surah name goes. */
@media (max-width: 767px) {
  [data-phone-scroll='medium'] .hero {
    --pace: 0.512;
  }

  [data-phone-scroll='short'] .hero {
    --pace: 0.366;
  }

  [data-phone-left='page'] .page.left {
    left: calc(var(--x0, 0px) + 262px * var(--s, 1));
    right: auto;
    top: calc(var(--y0, 0px) + 80px * var(--s, 1));
    width: calc(375px * var(--s, 1));
    height: calc(560px * var(--s, 1));
    padding: calc(56px * var(--s, 1)) calc(16px * var(--s, 1));
    font-size: max(9px, calc(16px * var(--s, 1)));
    color: #2B211B;
  }

  [data-phone-left='page'] .page.left .surah {
    color: #8A6A1F;
  }

  [data-phone-left='page'] .page.left .ref {
    color: #6B5E55;
  }

  [data-phone-left='page'] .page.left .meaning {
    display: none; /* too long for a page this small */
  }
}

/* TRYOUT, phase 5: set on <html> by ending-options.js. Once the user picks, move the chosen rules up to the ending's
   styles and delete the rest, with .book's transition and endAt/placeEnding in main.js if "After the book" wins. */

/* "Under the book", computers only. The ending shares the book's last screen: .close is pulled up over it, and when
   scrolling reaches the end (main.js sets .ended) the open book rises and shrinks by what main.js works out for the
   screen, and the ending fades in underneath. Going back is quicker than arriving. */
.book {
  transition: transform 700ms cubic-bezier(0.32, 0.72, 0, 1);
}

@media (min-width: 768px) {
  [data-ending='under']:not(.still) .hero.ended .book {
    transform: translateY(var(--end-y, 0px)) scale(var(--end-scale, 1));
    transition-duration: 1100ms;
  }

  [data-ending='under']:not(.still) .close {
    display: block;
    height: 100vh;
    height: 100svh;
    min-height: 0;
    margin-top: -100vh;
    margin-top: -100svh;
    padding: 0;
    pointer-events: none;
  }

  [data-ending='under']:not(.still) .close .air,
  [data-ending='under']:not(.still) .close .backdrop,
  [data-ending='under']:not(.still) .close .signoff {
    display: none; /* the open book and its own dust are the picture here */
  }

  [data-ending='under']:not(.still) .close .inner {
    --delay: 450ms; /* the words follow the book's move */
    position: absolute;
    top: var(--end-top, 75%);
    left: 0;
    right: 0;
    margin: 0 auto;
    padding: 0 1.5rem;
    visibility: hidden;
    transition: visibility 0s 300ms;
  }

  [data-ending='under']:not(.still) .hero.ended + .close .inner {
    visibility: visible;
    pointer-events: auto;
    transition: none;
  }
}

/* Button looks. "Gold and outline" is the default, above. */
[data-buttons='outline'] .button.primary {
  background: transparent;
  color: var(--color-accent);
}

[data-buttons='outline'] .button.primary:hover {
  border-color: var(--color-accent);
  background: rgba(212, 175, 55, 0.12);
}

[data-buttons='outline'] .button:not(.primary) {
  border-color: rgba(250, 250, 249, 0.3);
  color: var(--color-foreground);
}

[data-buttons='outline'] .button:not(.primary):hover {
  border-color: rgba(250, 250, 249, 0.6);
  background: rgba(250, 250, 249, 0.06);
}

[data-buttons='text'] .entry {
  gap: 0.5rem 2.5rem;
}

[data-buttons='text'] .button,
[data-buttons='text'] .button:hover,
[data-buttons='text'] .button.primary,
[data-buttons='text'] .button.primary:hover {
  position: relative;
  padding: 0 0.25rem;
  border-color: transparent;
  background: transparent;
  color: var(--color-foreground);
}

[data-buttons='text'] .button.primary,
[data-buttons='text'] .button.primary:hover {
  color: var(--color-accent);
}

[data-buttons='text'] .button::after {
  content: '';
  position: absolute;
  left: 0.25rem;
  right: 0.25rem;
  bottom: 11px;
  height: 1px;
  background: currentColor;
  opacity: 0.45;
  transform: scaleX(0.4);
  transition:
    opacity 200ms ease,
    transform 300ms cubic-bezier(0.16, 1, 0.3, 1);
}

[data-buttons='text'] .button:hover::after,
[data-buttons='text'] .button:focus-visible::after {
  opacity: 1;
  transform: none;
}

/* What sits behind the words, and the name at the very end. "Light and star" and "Show" are the defaults, above. */
[data-backdrop='plain'] .close .backdrop {
  display: none;
}

[data-backdrop='light'] .rosette {
  display: none;
}

[data-signoff='hide'] .signoff {
  display: none;
}

content.content:
1	// Phase 1: the hero scroll animation. Phase 2: the headline with the closed book. Phase 3: aayat on the open pages.
2	// Phase 5: the ending after the book, with its options.
3	// Retouched video frames of the Qur'an opening, drawn to a canvas by scroll position.
4	// Spec: WEBSITE-BUILD.md sections 2 to 4; the settings the user chose are under section 7.
5	
6	(() => {
7	  const clamp = (v) => Math.min(1, Math.max(0, v));
8	  const smoothstep = (t) => t * t * (3 - 2 * t);
9	
10	  // Frames --------------------------------------------------------------------
11	
12	  const SKIP = [39, 40]; // identical to f038, a hold in the source video
13	  const urls = [];
14	  for (let i = 0; i <= 88; i++) {
15	    if (!SKIP.includes(i)) urls.push(`assets/hero/frames/f${String(i).padStart(3, '0')}.png`);
16	  }
17	  const LAST = urls.length - 1; // 87 frames, indices 0..86
18	
19	  // Geometry, in pixels of the 1280x720 frames ----------------------------------
20	
21	  const SRC_W = 1280;
22	  const SRC_H = 720;
23	  const BOOK_LEFT = 255;   // left edge of the book; it never moves in the footage
24	  const BOOK_H = 580;      // y 70-650, centred on the frame's middle
25	  const SPINE = 640;       // right edge until the cover passes upright
26	  const OPEN_RIGHT = 1037; // right edge fully open
27	  const FEATHER_X = 180;   // how far the frame's rectangle fades into the stage
28	  const FEATHER_Y = 40;
29	
30	  // Timeline, in screen heights of scrolling on a computer -----------------------
31	  // Phones scroll less far for everything (--pace in styles.css).
32	
33	  const REST = 0.45;  // closed book with the headline
34	  const OPEN = 2.25;  // the cover opens (the same scrolling as when the user signed off phase 1)
35	  // Scrolling on the open book before the page moves on: the pages settle and the aayat can be read. It was 1.4
36	  // screens (0.4 to settle, 1 for the aayat) until the user found it too long; TRYOUT "Scroll once it opens".
37	  let hold = 0.35;
38	  let total = REST + OPEN + hold; // .hero in styles.css is one screen taller than this, through --timeline
39	  const NAME_GONE = 8; // the headline has faded out by this frame, early in the opening
40	
41	  // Smoothing ---------------------------------------------------------------------
42	
43	  // A mouse wheel scrolls in steps, so everything glides toward the scroll position instead of
44	  // jumping to it, and the book cross-fades between frames. The user chose this "slow glide" by eye.
45	  let glide = 0.28; // roughly the seconds it takes to close two thirds of the gap; 0 jumps straight there
46	  let blend = true; // cross-fade neighbouring frames, rather than showing whole frames only
47	  // Stopped between two frames, the cross-fade settles onto the nearer frame over this many seconds: held still, it looks blurred.
48	  const SHARPEN = 0.25;
49	  // Once scrolling reaches this, the aayat fade in by themselves (the transition on .group), not with the scroll.
50	  const APPEAR = REST + OPEN * 0.9;
51	
52	  // A book left half open opens or closes by itself once scrolling stops: toward the nearer end, or the way the
53	  // visitor was scrolling. 'off' leaves it where it stopped.
54	  let finish = 'direction';
55	  let finishSpeed = 1;     // screens of scrolling a second; a half-open book is about one screen from either end
56	  const FINISH_WAIT = 180; // ms without scrolling before it finishes
57	
58	  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
59	  const wide = matchMedia('(min-width: 768px)'); // "Under the book" is for computers only
60	  const hero = document.querySelector('.hero');
61	  const stage = hero.querySelector('.stage');
62	  const subject = stage.querySelector('.subject'); // the book and its aayat, moved together by atmosphere.js
63	  const canvas = subject.querySelector('canvas');
64	  const wordmark = stage.querySelector('.wordmark');
65	  const ctx = canvas.getContext('2d');
66	  const close = document.querySelector('.close'); // the ending, after the book
67	  const closeInner = close.querySelector('.inner');
68	
69	  const frames = []; // decoded images by index, filled in as they arrive
70	  const rights = []; // measured right edge of the book in each frame
71	  const started = new Set();
72	  const groups = []; // one element per group of aayat, filled in when aayat.json arrives
73	
74	  let scale = 1;      // footage pixels to CSS pixels, set on resize
75	  let pos = null;     // scroll position shown, in screens; lags the real one while gliding
76	  let painted = null; // position last shown
77	  let drawn = null;   // frame last drawn; fractional between frames
78	  let last = 0;       // time of the previous glide step, 0 when at rest
79	  let dirty = true;
80	  let queued = false;
81	  let visible = true;
82	  let showing = false; // whether the pages show aayat
83	  let current = -1;   // the group of aayat last picked
84	  let previous = -1;  // the last group shown, so the next pass shows a different one
85	  let moving = false; // still gliding toward the scroll position; atmosphere.js keeps the book still meanwhile
86	  let sharpen = 1;    // 0 while moving, 1 once settled onto a whole frame
87	  let direction = 0;  // 1 when the visitor last scrolled down, -1 up
88	  let lastY = scrollY;
89	  let touching = false;
90	  let finishTimer = 0;
91	  let autoScroll = 0; // the animation frame of a scroll the page started itself, 0 when none
92	  let ended = false;  // scrolling has reached the end of the book's screens
93	
94	  // Loading -----------------------------------------------------------------------
95	
96	  function load(i) {
97	    if (started.has(i)) return;
98	    started.add(i);
99	    const img = new Image();
100	    img.src = urls[i];
101	    img.decode().then(
102	      () => {
103	        frames[i] = img;
104	        rights[i] = measureRight(img);
105	        if (i >= LAST - 3) place(); // the open book's measured edge sets where the pages are
106	        dirty = true;
107	        schedule();
108	      },
109	      () => console.warn(`Frame missing: ${urls[i]}`), // the nearest loaded frame is drawn instead
110	    );
111	  }
112	
113	  // First and last frames, then coarse to fine, so scrubbing works before everything arrives.
114	  function loadAll() {
115	    load(0);
116	    load(LAST);
117	    for (const step of [8, 4, 2, 1]) {
118	      for (let i = 0; i <= LAST; i += step) load(i);
119	    }
120	  }
121	
122	  // Once the cover passes upright its cream lining faces the camera, so the book's right
123	  // edge is the rightmost bright pixel along the middle row, and never less than the spine.
124	  const probe = document.createElement('canvas');
125	  probe.width = SRC_W;
126	  probe.height = 1;
127	  const probeCtx = probe.getContext('2d', { willReadFrequently: true });
128	
129	  function measureRight(img) {
130	    try {
131	      probeCtx.drawImage(img, 0, SRC_H / 2, SRC_W, 1, 0, 0, SRC_W, 1);
132	      const px = probeCtx.getImageData(0, 0, SRC_W, 1).data;
133	      for (let x = SRC_W - 1; x > SPINE; x--) {
134	        if (px[x * 4] + px[x * 4 + 1] + px[x * 4 + 2] > 300) return x + 1;
135	      }
136	      return SPINE;
137	    } catch {
138	      return null; // pixels unreadable, e.g. opened as a file rather than through serve.js
139	    }
140	  }
141	
142	  // Averaged over nearby frames so the centring glides instead of stepping.
143	  function rightEdge(i) {
144	    let sum = 0;
145	    let n = 0;
146	    for (let j = Math.max(0, i - 3); j <= Math.min(LAST, i + 3); j++) {
147	      if (rights[j] != null) {
148	        sum += rights[j];
149	        n++;
150	      }
151	    }
152	    return n ? sum / n : SPINE + ((OPEN_RIGHT - SPINE) * i) / LAST;
153	  }
154	
155	  // Aayat -------------------------------------------------------------------------
156	  // The exact text comes from aayat.json, written by fetch-aayat.js from Quran.com. Never typed by hand.
157	
158	  const aayat = document.createElement('div');
159	  aayat.className = 'aayat';
160	  subject.append(aayat);
161	
162	  function el(tag, className, text) {
163	    const node = document.createElement(tag);
164	    node.className = className;
165	    if (text) node.textContent = text;
166	    return node;
167	  }
168	
169	  // Arabic on the right page, the first page in a mushaf, each ayah closed by its numbered marker.
170	  // The left page carries the surah name, reference and English meaning.
171	  function renderGroup({ ref, surah, aayat: verses }) {
172	    const group = el('section', 'group');
173	    const right = el('div', 'page right');
174	    const arabic = el('p', 'arabic');
175	    arabic.lang = 'ar';
176	    arabic.dir = 'rtl';
177	    for (const { key, text } of verses) {
178	      const marker = el('span', 'marker', `۝${Number(key.split(':')[1]).toLocaleString('ar-u-nu-arab')}`);
179	      marker.setAttribute('aria-hidden', 'true');
180	      arabic.append(`${text} `, marker, ' ');
181	    }
182	    right.append(arabic);
183	    const left = el('div', 'page left');
184	    left.append(
185	      el('p', 'surah', surah),
186	      el('p', 'meaning', verses.map((v) => v.translation).join(' ')),
187	      el('p', 'ref', ref.replace('-', '–')),
188	    );
189	    group.append(right, left);
190	    return group;
191	  }
192	
193	  fetch('aayat.json')
194	    .then((res) => res.json())
195	    .then((data) => {
196	      for (const g of data.groups) groups.push(aayat.appendChild(renderGroup(g)));
197	      fit();
198	      dirty = true;
199	      schedule();
200	    })
201	    .catch(() => console.warn('No aayat yet: run fetch-aayat.js'));
202	
203	  // Where the open book's pages are: CSS lays the text over them from these.
204	  function place() {
205	    const open = (BOOK_LEFT + rightEdge(LAST)) / 2;
206	    stage.style.setProperty('--s', scale);
207	    stage.style.setProperty('--x0', `${canvas.clientWidth / 2 - open * scale}px`);
208	    stage.style.setProperty('--y0', `${(canvas.clientHeight - SRC_H * scale) / 2}px`);
209	    stage.style.setProperty('--book-h', `${BOOK_H * scale}px`);
210	    placeEnding();
211	  }
212	
213	  // Shrinks a page's text until it fits, for aayat longer than the page holds at its normal size.
214	  function fit() {
215	    for (const page of aayat.querySelectorAll('.page')) {
216	      page.style.fontSize = '';
217	      let size = parseFloat(getComputedStyle(page).fontSize);
218	      while (page.scrollHeight > page.clientHeight && size > 10) {
219	        size *= 0.94;
220	        page.style.fontSize = `${size}px`;
221	      }
222	    }
223	  }
224	
225	  // One group at a time, picked at random each time the pages come into view. It fades in by itself once
226	  // the book is open and stays; scrolling back before that fades it out, so the next pass picks again.
227	  // Under reduced motion a random group is simply shown.
228	  function showAayat(s, still) {
229	    const show = still || s >= APPEAR;
230	    if (show === showing || !groups.length) return;
231	    showing = show;
232	    if (show) current = pick();
233	    groups.forEach((group, k) => {
234	      group.style.opacity = show && k === current ? 1 : 0;
235	    });
236	  }
237	
238	  // A random group, never the one shown last time.
239	  function pick() {
240	    let k;
241	    do k = Math.floor(Math.random() * groups.length);
242	    while (groups.length > 1 && k === previous);
243	    return (previous = k);
244	  }
245	
246	  // The ending ----------------------------------------------------------------------
247	  // One line and two ways in, on the screen after the book. It rises gently into view the first time it scrolls in
248	  // (styles.css), except under reduced motion.
249	
250	  if (!reduceMotion.matches) {
251	    close.classList.add('pending');
252	    const reveal = new IntersectionObserver(
253	      ([entry]) => {
254	        if (!entry.isIntersecting || under()) return; // under the book, the words wait for the book (endAt)
255	        close.classList.remove('pending');
256	        reveal.disconnect();
257	      },
258	      { rootMargin: '0px 0px -15% 0px' },
259	    );
260	    reveal.observe(closeInner);
261	  }
262	
263	  // TRYOUT "Under the book": when scrolling reaches the end, the open book rises and shrinks so the ending fits
264	  // under it (styles.css). Scrolling back a little undoes it; the gap between the two points stops it flickering.
265	  function endAt(s) {
266	    const end = s >= total - 0.1 || (ended && s > total - 0.4);
267	    if (end === ended) return;
268	    hero.classList.toggle('ended', (ended = end));
269	    if (under()) close.classList.toggle('pending', !end); // the words arrive in order once the book has made room
270	  }
271	
272	  function under() {
273	    return document.documentElement.dataset.ending === 'under' && wide.matches && !reduceMotion.matches;
274	  }
275	
276	  // Tells styles.css how long the timeline is, so the hero's height matches it.
277	  function applyTimeline() {
278	    total = REST + OPEN + hold;
279	    hero.style.setProperty('--timeline', total);
280	  }
281	
282	  // How far the book rises and shrinks for "Under the book", and where the ending goes: the book stays full size if
283	  // both fit, and the two sit centred on the screen together. In footage pixels the open book, with the page edges
284	  // that reach past it, runs from 10 above its top to 44 below its bottom.
285	  function placeEnding() {
286	    const h = canvas.clientHeight;
287	    const tall = (BOOK_H + 54) * scale;
288	    const above = (BOOK_H / 2 + 10) * scale; // from the middle of the screen to the top of the book
289	    const gap = Math.max(24, h * 0.05);
290	    const text = closeInner.offsetHeight;
291	    const k = Math.min(1, Math.max(0.55, (h - 3 * gap - text) / tall));
292	    const top = Math.max(gap, (h - tall * k - gap - text) / 2);
293	    const vars = document.documentElement.style;
294	    vars.setProperty('--end-scale', k);
295	    vars.setProperty('--end-y', `${top - h / 2 + above * k}px`);
296	    vars.setProperty('--end-top', `${top + tall * k + gap}px`);
297	  }
298	
299	  // Drawing -----------------------------------------------------------------------
300	
301	  // Cross-fades the two frames either side of a position, or while they are still loading, draws
302	  // the nearest frame that has arrived. Returns false while no frame has loaded yet.
303	  function draw(at) {
304	    const a = Math.floor(at);
305	    const b = Math.min(a + 1, LAST);
306	    const f = at - a;
307	    const fade = f > 0 && !!frames[a] && !!frames[b];
308	    const base = fade ? a : nearestLoaded(Math.round(at));
309	    if (base < 0) return false;
310	
311	    const width = canvas.clientWidth;
312	    const height = canvas.clientHeight;
313	    // The book is centred by choosing which part of the frame is drawn, never by moving the canvas.
314	    const right = rightEdge(a) + (rightEdge(b) - rightEdge(a)) * f;
315	    const centre = (BOOK_LEFT + right) / 2;
316	    const w = SRC_W * scale;
317	    const h = SRC_H * scale;
318	    const x = width / 2 - centre * scale;
319	    const y = (height - h) / 2;
320	
321	    ctx.globalCompositeOperation = 'source-over';
322	    ctx.clearRect(0, 0, width, height);
323	    ctx.drawImage(frames[base], x, y, w, h);
324	    if (fade) {
325	      ctx.globalAlpha = f;
326	      ctx.drawImage(frames[b], x, y, w, h);
327	      ctx.globalAlpha = 1;
328	    }
329	    featherEdges(x, y, w, h);
330	
331	    // Where the book is on screen, so atmosphere.js keeps its dust and light off it.
332	    const top = y + ((SRC_H - BOOK_H) / 2) * scale;
333	    hero.book = { left: x + BOOK_LEFT * scale, right: x + right * scale, top, bottom: top + BOOK_H * scale, scale };
334	    return true;
335	  }
336	
337	  // Fades a drawn rectangle out at its edges so it never shows against the stage.
338	  function featherEdges(x, y, w, h) {
339	    ctx.globalCompositeOperation = 'destination-in';
340	    ctx.fillStyle = feather(ctx.createLinearGradient(x, 0, x + w, 0), FEATHER_X / SRC_W);
341	    ctx.fillRect(x, y, w, h);
342	    ctx.fillStyle = feather(ctx.createLinearGradient(0, y, 0, y + h), FEATHER_Y / SRC_H);
343	    ctx.fillRect(x, y, w, h);
344	    ctx.globalCompositeOperation = 'source-over';
345	  }
346	
347	  function feather(gradient, edge) {
348	    gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
349	    gradient.addColorStop(edge, '#000');
350	    gradient.addColorStop(1 - edge, '#000');
351	    gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
352	    return gradient;
353	  }
354	
355	  // How far the hero has been scrolled, in computer screen heights (0 to total).
356	  function targetScroll() {
357	    const range = hero.offsetHeight - stage.offsetHeight;
358	    return range > 0 ? clamp(-hero.getBoundingClientRect().top / range) * total : 0;
359	  }
360	
361	  // The book's frame at a scroll position; smoothstep eases into and out of the opening.
362	  function frameAt(s) {
363	    return smoothstep(clamp((s - REST) / OPEN)) * LAST;
364	  }
365	
366	  function nearestLoaded(i) {
367	    for (let d = 0; d <= LAST; d++) {
368	      if (frames[i - d]) return i - d;
369	      if (frames[i + d]) return i + d;
370	    }
371	    return -1;
372	  }
373	
374	  function schedule() {
375	    if (queued) return;
376	    queued = true;
377	    requestAnimationFrame(step);
378	  }
379	
380	  // Each animation frame, moves part of the way toward the scroll position and keeps going until it arrives,
381	  // then settles onto a whole frame. Uses elapsed time, so it feels the same on 60 Hz and 144 Hz screens.
382	  function step(now) {
383	    queued = false;
384	    if (!visible) {
385	      last = 0;
386	      return;
387	    }
388	    const target = targetScroll();
389	    const dt = last ? Math.min(now - last, 50) / 1000 : 1 / 60;
390	    if (pos === null || reduceMotion.matches || !glide) {
391	      pos = target;
392	    } else {
393	      pos += (target - pos) * (1 - Math.exp(-dt / glide));
394	      if (Math.abs(target - pos) < 0.0005) pos = target;
395	    }
396	    sharpen = pos === target ? Math.min(1, sharpen + dt / SHARPEN) : Math.max(0, sharpen - (3 * dt) / SHARPEN);
397	    last = pos === target && sharpen === 1 ? 0 : now;
398	    paint();
399	    if (moving !== (pos !== target)) {
400	      moving = pos !== target;
401	      hero.dispatchEvent(new Event(moving ? 'bookmove' : 'bookrest'));
402	    }
403	    if (last) schedule();
404	  }
405	
406	  // Updates the headline and aayat, and redraws the book only when its frame, the size or the loaded
407	  // frames have changed. Under reduced motion the book is shown open and the headline stays.
408	  function paint() {
409	    if (pos === null) return;
410	    const still = reduceMotion.matches;
411	    const exact = frameAt(pos);
412	    const whole = Math.round(exact);
413	    const frame = still ? LAST : blend ? exact + (whole - exact) * smoothstep(sharpen) : whole;
414	    if (pos !== painted || dirty) {
415	      wordmark.style.opacity = still ? 1 : 1 - clamp(frame / NAME_GONE);
416	      showAayat(pos, still);
417	      endAt(pos);
418	      painted = pos;
419	    }
420	    if (frame !== drawn || dirty) {
421	      if (draw(frame)) {
422	        drawn = frame;
423	        dirty = false;
424	      }
425	    }
426	  }
427	
428	  function resize() {
429	    const width = canvas.clientWidth;
430	    const height = canvas.clientHeight;
431	    const dpr = Math.min(devicePixelRatio || 1, 2);
432	    canvas.width = Math.round(width * dpr);
433	    canvas.height = Math.round(height * dpr);
434	    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
435	    ctx.imageSmoothingQuality = 'high';
436	    // One size for the whole opening: the open book always fits, and the 720p footage is
437	    // never stretched past its own size.
438	    scale = Math.min((height * 0.8) / BOOK_H, (width * 0.88) / (OPEN_RIGHT - BOOK_LEFT), 1);
439	    place();
440	    fit();
441	    dirty = true;
442	    paint(); // draw now: resizing the canvas has just cleared it
443	    schedule(); // the hero's height follows the window, so the scroll position may now mean a different frame
444	  }
445	
446	  // Reduced motion: no scrubbing, just the open book, and only its frame is loaded.
447	  function applyMotion() {
448	    document.documentElement.classList.toggle('still', reduceMotion.matches);
449	    if (reduceMotion.matches) load(LAST);
450	    else loadAll();
451	    dirty = true;
452	    schedule();
453	  }
454	
455	  // TRYOUT --------------------------------------------------------------------------
456	  // Options shown only on this PC or a phone on the same wifi. Once the user picks: put the picks in the
457	  // settings above and in styles.css, then delete this block, the TRYOUT part of styles.css and the
458	  // unused Arabic font in index.html.
459	
460	  if (/^(localhost|[\d.]+)$/.test(location.hostname)) {
461	    const narrow = matchMedia('(max-width: 767px)').matches;
462	    const panel = document.createElement('details');
463	    panel.className = 'tryout';
464	    panel.open = !narrow; // closed to start with on phones, where it would cover the book
465	    panel.innerHTML = '<summary>Options</summary>';
466	    document.body.append(panel);
467	
468	    // Groups of rows, each under a heading that opens and closes. Rows go into the group named last, and naming a
469	    // group again adds to it. atmosphere.js and ending-options.js use this too; `first` puts a new group at the top.
470	    let group = panel;
471	    window.tryoutGroup = (title, { open = false, first = false } = {}) => {
472	      group = [...panel.querySelectorAll(':scope > details')].find((g) => g.dataset.title === title);
473	      if (group) return;
474	      group = document.createElement('details');
475	      group.dataset.title = title;
476	      group.open = open;
477	      group.append(el('summary', '', title));
478	      if (first) panel.querySelector('summary').after(group);
479	      else panel.append(group);
480	    };
481	
482	    // A row of buttons; the one matching `initial` starts pressed. atmosphere.js adds its rows with this too.
483	    window.addOption = (label, choices, initial, pick) => {
484	      const row = document.createElement('div');
485	      row.append(el('span', '', label));
486	      for (const [text, value] of Object.entries(choices)) {
487	        const b = el('button', '', text);
488	        b.type = 'button';
489	        b.setAttribute('aria-pressed', value === initial);
490	        b.addEventListener('click', () => {
491	          for (const other of row.querySelectorAll('button')) other.setAttribute('aria-pressed', other === b);
492	          pick(value);
493	        });
494	        row.append(b);
495	      }
496	      group.append(row);
497	    };
498	
499	    // A slider with its value shown beside it, in the words `format` gives.
500	    window.addSlider = (label, min, max, step, initial, format, pick) => {
501	      const row = document.createElement('div');
502	      const range = el('input', '');
503	      Object.assign(range, { type: 'range', min, max, step, value: initial });
504	      range.setAttribute('aria-label', label);
505	      const shown = el('output', '', format(initial));
506	      range.addEventListener('input', () => {
507	        const value = Number(range.value);
508	        shown.textContent = format(value);
509	        pick(value);
510	      });
511	      row.append(el('span', '', label), range, shown);
512	      group.append(row);
513	    };
514	
515	    // A free-text field: typing updates the page as you go. wordmark-options.js and ending-options.js use this for
516	    // the headline, the sentence under it, the closing line, the button words and the name at the very end, so any
517	    // of them can be typed exactly as wanted, not only chosen from a preset. Returns the input, so a preset button
518	    // can fill it in too and the field always shows what the page currently says.
519	    window.addText = (label, initial, pick) => {
520	      const row = document.createElement('div');
521	      const field = el('input', '');
522	      Object.assign(field, { type: 'text', value: initial });
523	      field.setAttribute('aria-label', label);
524	      field.addEventListener('input', () => pick(field.value));
525	      row.append(el('span', '', label), field);
526	      group.append(row);
527	      return field;
528	    };
529	
530	    const redraw = () => {
531	      dirty = true;
532	      schedule();
533	    };
534	    const retime = (set) => (value) => {
535	      set(value);
536	      redraw();
537	    };
538	    const setData = (key) => (value) => {
539	      document.documentElement.dataset[key] = value;
540	      fit();
541	    };
542	    tryoutGroup('Ending', { open: true, first: true });
543	    addOption('Scroll once it opens', { 'As before': 1.4, Less: 0.7, Least: 0.35 }, hold, (v) => {
544	      hold = v;
545	      applyTimeline();
546	      redraw();
547	    });
548	    tryoutGroup('Opening and aayat');
549	    const glideText = (v) => (v ? `${v.toFixed(2)} s${v === 0.28 ? ' (your pick)' : ''}` : 'Off');
550	    addSlider('Opening glide', 0, 0.5, 0.01, glide, glideText, retime((v) => (glide = v)));
551	    addOption('Blend frames', { Off: false, On: true }, blend, retime((v) => (blend = v)));
552	    addOption('Half-open book', { Stays: 'off', 'Nearer end': 'nearest', 'Way you scrolled': 'direction' }, finish, (v) => (finish = v));
553	    addSlider('Auto open/close speed', 25, 300, 5, finishSpeed * 100, (v) => `${v}%`, (v) => (finishSpeed = v / 100));
554	    addOption('Arabic lettering', { 'Amiri Quran': 'amiri', Scheherazade: 'scheherazade' }, 'amiri', setData('arabic'));
555	    addOption('Left page', { 'Surah name': 'name', 'English meaning': 'meaning' }, 'name', setData('left'));
556	    if (narrow) {
557	      const phoneScroll = setData('phoneScroll');
558	      phoneScroll('short');
559	      addOption('Scroll length', { Long: 'long', Medium: 'medium', Short: 'short' }, 'short', (v) => {
560	        phoneScroll(v);
561	        redraw();
562	      });
563	      addOption('Surah name', { 'Under the book': 'under', 'On the page': 'page' }, 'under', setData('phoneLeft'));
564	    }
565	  }
566	
567	  // Finishing the opening ------------------------------------------------------------
568	
569	  function onScroll() {
570	    schedule();
571	    if (autoScroll) return; // the page's own scrolling
572	    direction = Math.sign(scrollY - lastY) || direction;
573	    lastY = scrollY;
574	    waitToFinish();
575	  }
576	
577	  function waitToFinish() {
578	    clearTimeout(finishTimer);
579	    finishTimer = setTimeout(finishOpening, FINISH_WAIT);
580	  }
581	
582	  function finishOpening() {
583	    if (finish === 'off' || touching || autoScroll || reduceMotion.matches || !visible) return;
584	    const progress = (targetScroll() - REST) / OPEN;
585	    if (progress <= 0.002 || progress >= 0.998) return; // closed or open already
586	    const open = finish === 'nearest' ? progress >= 0.5 : direction > 0;
587	    scrollToScreens(open ? REST + OPEN : REST);
588	  }
589	
590	  // Scrolls the page to a point on the hero's timeline, easing in and out.
591	  function scrollToScreens(s) {
592	    const range = hero.offsetHeight - stage.offsetHeight;
593	    const from = scrollY;
594	    const distance = hero.getBoundingClientRect().top + scrollY + (s / total) * range - from;
595	    const duration = Math.max(300, (1000 * Math.abs(distance)) / innerHeight / finishSpeed); // a short finish still eases
596	    const start = performance.now();
597	    const tick = (now) => {
598	      const t = Math.min(1, (now - start) / duration);
599	      const eased = t < 0.5 ? 4 * t * t * t : 1 - (2 - 2 * t) ** 3 / 2;
600	      scrollTo(0, from + distance * eased);
601	      autoScroll = t < 1 ? requestAnimationFrame(tick) : 0;
602	      if (!autoScroll) lastY = scrollY;
603	    };
604	    autoScroll = requestAnimationFrame(tick);
605	  }
606	
607	  // Any scrolling by the visitor takes over from the page's own.
608	  function takeOver() {
609	    cancelAnimationFrame(autoScroll);
610	    autoScroll = 0;
611	    lastY = scrollY;
612	  }
613	
614	  addEventListener('scroll', onScroll, { passive: true });
615	  for (const type of ['wheel', 'keydown', 'mousedown']) addEventListener(type, takeOver, { passive: true });
616	  addEventListener(
617	    'touchstart',
618	    () => {
619	      touching = true;
620	      takeOver();
621	    },
622	    { passive: true },
623	  );
624	  addEventListener(
625	    'touchend',
626	    () => {
627	      touching = false;
628	      waitToFinish();
629	    },
630	    { passive: true },
631	  );
632	  document.fonts.addEventListener('loadingdone', fit); // text changes size when its font arrives
633	  reduceMotion.addEventListener('change', applyMotion);
634	  new ResizeObserver(resize).observe(canvas);
635	  new ResizeObserver(placeEnding).observe(closeInner); // the ending's height changes with its words and fonts
636	  new IntersectionObserver(([entry]) => {
637	    visible = entry.isIntersecting;
638	    dirty = true;
639	    schedule();
640	  }).observe(hero);
641	  applyTimeline();
642	  applyMotion();
643	})();
