/* The top of the page was "very empty" (the user, 2026-09-13). From taste-skill:redesign-skill's audit: no name or
   navigation, nothing telling a visitor the page scrolls, and wide empty sides round the narrow closed book. Touch
   targets and focus rings from ui-ux-pro-max. */

/* A hint that the page scrolls, under the headline while the book is closed: two words and a fine gold line that runs
   down, over and over (MASTER.md's scroll-story pattern asks for a cue). main.js shows it only where the space under
   the book holds it (.roomy); it fades with the headline, and is left out under reduced motion. */
.scroll-hint {
  display: none;
  flex-direction: column;
  align-items: center;
  gap: 0.65rem;
  margin-top: 1.5rem;
  padding-left: 0.24em; /* balances the letter-spacing after the last letter */
  font-size: 0.6875rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--color-muted-foreground);
}

.roomy .scroll-hint {
  display: flex;
}

.scroll-hint::after {
  content: '';
  width: 1px;
  height: 2rem;
  background: linear-gradient(var(--color-accent), rgba(212, 175, 55, 0));
  transform-origin: top;
  animation: hint 2.6s cubic-bezier(0.65, 0, 0.35, 1) infinite;
}

@keyframes hint {
  0% {
    opacity: 1;
    transform: scaleY(0);
  }

  55% {
    opacity: 1;
    transform: scaleY(1);
  }

  100% {
    opacity: 0;
    transform: scaleY(1);
  }
}

/* Either side of the closed book, on computers: a small gold heading and a few lines, set toward the book. --s is the
   book's scale (main.js); the closed book is 385 footage pixels wide. They fade with the headline, long before the
   opening cover reaches them. */
.beside {
  position: absolute;
  z-index: 1;
  top: 50%;
  display: none;
  width: min(15rem, calc(50% - 192px * var(--s, 1) - 7rem));
  translate: 0 -50%;
}

@media (min-width: 1024px) {
  .beside {
    display: block;
  }
}

.beside.left {
  right: calc(50% + 192px * var(--s, 1) + clamp(2.5rem, 5vw, 5rem));
  text-align: right;
}

.beside.right {
  left: calc(50% + 192px * var(--s, 1) + clamp(2.5rem, 5vw, 5rem));
}

.beside .label {
  margin: 0;
  font-family: var(--font-display);
  font-size: 0.6875rem;
  font-weight: 500;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--color-accent);
}

.beside.left .label {
  margin-right: -0.24em; /* the letter-spacing after the last letter would hold it off the edge */
}

.beside .label::after {
  content: '';
  display: block;
  width: 1.5rem;
  height: 1px;
  margin: 0.9rem 0 0.75rem;
  background: currentColor;
  opacity: 0.5;
}

.beside.left .label::after {
  margin-right: 0.24em;
  margin-left: auto;
}

.beside ul {
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 1rem;
  font-weight: 300;
  line-height: 1.85;
  letter-spacing: 0.02em;
  color: rgba(250, 250, 249, 0.82);
}

/* The top bar: the name on the left, the two ways in on the right (the user's list; About and Contact go at the
   bottom). It sits on the scene over a short fade of the background colour, so dust never runs through the words, with
   no blur: blurring a moving canvas costs every frame on weak devices. main.js slides it away while the visitor scrolls
   down and brings it back on the way up. */
.topbar {
  position: fixed;
  z-index: 2; /* over the book's screen and the ending */
  top: 0;
  right: 0;
  left: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  height: 4.5rem;
  padding: 0 clamp(1rem, 3vw, 2.5rem);
  transition: transform 500ms cubic-bezier(0.32, 0.72, 0, 1);
}

.topbar::before {
  content: '';
  position: absolute;
  z-index: -1;
  inset: 0;
  background: linear-gradient(rgba(31, 26, 24, 0.85), rgba(31, 26, 24, 0));
  pointer-events: none;
}

.topbar.away:not(:focus-within) {
  transform: translateY(-100%); /* a keyboard user's focus brings it back */
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  min-height: 44px;
  font-family: var(--font-display);
  font-size: 0.8125rem;
  font-weight: 500;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--color-accent);
  text-decoration: none;
}

/* The small star from the ending's ornament, like the gold tooling on the cover. It turns an eighth on hover. */
.brand .mark {
  flex: none;
  width: 1.25rem;
  height: 1.25rem;
  overflow: visible;
  fill: none;
  stroke: var(--color-accent);
  stroke-width: 1;
  transition: rotate 700ms cubic-bezier(0.16, 1, 0.3, 1);
}

.brand .mark * {
  vector-effect: non-scaling-stroke;
}

.brand .mark circle {
  fill: var(--color-accent);
  stroke: none;
}

.brand:hover .mark {
  rotate: 45deg;
}

.topbar nav {
  display: flex;
  align-items: center;
  gap: clamp(1.25rem, 2.5vw, 2.25rem);
}

.topbar nav a {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  font-size: 0.875rem;
  letter-spacing: 0.06em;
  color: rgba(250, 250, 249, 0.78);
  text-decoration: none;
  white-space: nowrap;
  transition:
    color 200ms ease,
    background-color 200ms ease,
    border-color 200ms ease,
    transform 200ms ease;
}

/* A fine gold underline that draws out on hover. */
.topbar nav a::after {
  content: '';
  position: absolute;
  right: 0;
  bottom: 10px;
  left: 0;
  height: 1px;
  background: var(--color-accent);
  transform: scaleX(0);
  transition: transform 300ms cubic-bezier(0.16, 1, 0.3, 1);
}

.topbar nav a:hover {
  color: var(--color-foreground);
}

.topbar nav a:hover::after,
.topbar nav a:focus-visible::after {
  transform: none;
}

/* The lessons link as a small gold outline, quieter than the ending's solid button. */
.topbar .outlined {
  min-height: 40px;
  padding: 0 1.1rem;
  border: 1px solid rgba(212, 175, 55, 0.6);
  border-radius: 4px;
  color: var(--color-accent);
}

.topbar .outlined::after {
  display: none;
}

.topbar .outlined:hover {
  border-color: var(--color-accent);
  background: rgba(212, 175, 55, 0.1);
  color: var(--color-accent);
}

.topbar .outlined:active {
  transform: scale(0.98);
}

.brand:focus-visible,
.topbar nav a:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 4px;
}

@media (pointer: coarse) {
  .topbar .outlined {
    min-height: 44px;
  }
}

@media (max-width: 479px) {
  .topbar {
    height: 4rem;
  }

  .topbar nav {
    gap: 1rem;
  }

  .topbar nav a {
    font-size: 0.8125rem;
  }

  .topbar .outlined {
    padding: 0 0.8rem;
  }

  /* Too narrow for the name beside both links: the star stands in for it, and screen readers still get the name. */
  .brand .name {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}

/* The top bar and the words beside the book arrive a beat after the page loads, one after another. */
@media (prefers-reduced-motion: no-preference) {
  .topbar > *,
  .beside > * {
    animation: arrive 1000ms cubic-bezier(0.16, 1, 0.3, 1) backwards;
    animation-delay: calc(250ms + var(--i, 0) * 120ms);
  }

  .topbar > * {
    --from: -0.5rem;
  }

  .topbar nav {
    --i: 1;
  }

  .beside .label {
    --i: 2;
  }

  .beside ul {
    --i: 3;
  }
}

@keyframes arrive {
  from {
    opacity: 0;
    translate: 0 var(--from, 0.5rem);
  }
}

