    const r = size / 2;
    const gradient = g.createRadialGradient(r, r, 0, r, r, r);
    for (const [at, color] of stops) gradient.addColorStop(at, color);
    g.fillStyle = gradient;
    g.fillRect(0, 0, size, size);

