/* The bottom of the page: who teaches and how to get in touch, then the links (the user's list: Free Qaida, One-to-one
   lessons, About the teacher, Contact). From taste-skill:minimalist-skill: generous space, hairline dividers, no cards
   or shadows, 4px corners, a quiet rise into view, in the page's own gold, Cinzel and Jost rather than the skill's fonts.
   Form rules from ui-ux-pro-max: a visible label on every field, the reason under the field, 48px fields, autofill. */
.footer {
  position: relative;
  padding: clamp(5rem, 10vw, 8rem) clamp(1.5rem, 5vw, 4rem) 2rem;
  border-top: 1px solid rgb(var(--rgb-foreground) / 0.1);
}

/* The small star from the cover's tooling, sitting on the line. */
.footer-mark {
  position: absolute;
  top: 0;
  left: 50%;
  width: 3.25rem;
  height: 1.25rem;
  padding: 0 1rem;
  translate: -50% -50%;
  overflow: visible;
  background: var(--color-background);
  fill: none;
  stroke: var(--color-accent);
  stroke-width: 1;
}

.footer-mark * {
  vector-effect: non-scaling-stroke;
}

.footer-mark circle {
  fill: var(--color-accent);
  stroke: none;
}

.footer-inner {
  display: grid;
  gap: 4.5rem;
  max-width: 64rem;
  margin: 0 auto;
}

@media (min-width: 900px) {
  .footer-inner {
    grid-template-columns: 5fr 6fr;
    gap: clamp(4rem, 8vw, 7rem);
  }
}

.about,
.contact {
  scroll-margin-top: 6rem; /* clear of the top bar when a link jumps here */
}

.footer .lead {
  margin: 0;
  font-size: clamp(1.625rem, 1.3rem + 1.2vw, 2.25rem);
  font-weight: 300;
  line-height: 1.25;
  text-wrap: balance;
}

.years,
.intro {
  margin: 0.75rem 0 0;
  line-height: 1.6;
  color: var(--color-muted-foreground);
}

.bio {
  max-width: 34ch;
  margin: 1.75rem 0 0;
  font-size: 1.0625rem;
  font-weight: 300;
  line-height: 1.7;
  color: rgb(var(--rgb-foreground) / 0.82);
  text-wrap: pretty;
}

.reach {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1rem;
  margin-top: 2rem;
}

.whatsapp {
  gap: 0.625rem;
}

.whatsapp svg {
  width: 1.125rem;
  height: 1.125rem;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linejoin: round;
}

.show-form {
  display: none; /* TRYOUT "Email form: Behind a button" shows it */
  background: none;
  font-family: inherit;
}

/* "or send an email", between two fine rules. */
.or {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin: 2.5rem 0 0;
  font-size: 0.8125rem;
  letter-spacing: 0.04em;
  color: var(--color-muted-foreground);
}

.or::before,
.or::after {
  content: '';
  flex: 1;
  height: 1px;
  background: rgb(var(--rgb-foreground) / 0.1);
}

.enquiry {
  display: grid;
  gap: 1.25rem;
  margin-top: 1.75rem;
}

.field {
  display: grid;
  gap: 0.5rem;
}

.field label {
  font-size: 0.8125rem;
  letter-spacing: 0.04em;
  color: var(--color-muted-foreground);
}

.field input,
.field textarea {
  width: 100%;
  min-height: 48px;
  padding: 0.75rem 0.875rem;
  border: 1px solid rgb(var(--rgb-foreground) / 0.16);
  border-radius: 4px;
  background: rgb(var(--rgb-foreground) / 0.03);
  font: inherit;
  font-size: 1rem; /* 16px, so phones don't zoom in when a field is tapped */
  font-weight: 300;
  color: var(--color-foreground);
  transition:
    border-color 200ms ease,
    background-color 200ms ease;
}

.field textarea {
  min-height: 7.5rem;
  line-height: 1.6;
  resize: vertical;
}

.field input:hover,
.field textarea:hover {
  border-color: rgb(var(--rgb-foreground) / 0.3);
}

.field input:focus-visible,
.field textarea:focus-visible {
  border-color: var(--color-accent);
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.field [aria-invalid='true'] {
  border-color: var(--color-error);
}

.error {
  margin: 0;
  font-size: 0.8125rem;
  line-height: 1.5;
  color: var(--color-error);
}

.send {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem 1.5rem;
  margin-top: 0.5rem;
}

.enquiry .button {
  font-family: inherit;
}

.button:disabled {
  opacity: 0.6;
  cursor: progress;
}

.privacy {
  margin: 0;
  font-size: 0.8125rem;
  color: var(--color-muted-foreground);
}

.status {
  margin: 0;
